/*

The inputs to this function are:
- x: pointer to an array of float values (input), with at least n elements readable.
- n: number of elements in x to process (input), counted in float elements.

Behavior:
- If n < 2, the function returns 0.0f.
- Otherwise, it computes the population standard deviation of the first n elements of x using two scalar loops equivalent to:
  1) Compute the mean:
     sum = 0.0f;
     for (i = 0; i < n; i++) {
       sum += x[i];
     }
     mean = sum / (float)n;
  2) Compute the mean squared deviation:
     ss = 0.0f;
     for (i = 0; i < n; i++) {
       float d = x[i] - mean;
       ss += d * d;
     }
  3) Return sqrtf(ss / (float)n).

Preconditions:
- If n > 0, x must be non-NULL and point to at least n readable float elements.

Side effects and return value:
- The function does not modify memory visible to the caller.
- Returns 0.0f when n < 2; otherwise returns the population standard deviation of x[0..n-1] as described above.

The actual implementation may use SVE, but the semantics are exactly as described above.
*/

/* [OUTPUT]
Your goal is to implement the requirements described above using Arm SVE (ACLE) intrinsics.
The function interface is shown below.
END_OUTPUT */
float simd_stdev_f32_sve(const float* x, size_t n) {
}

#include <cstddef>
#include <arm_sve.h>
#include "math.h"
float simd_stdev_f32_sve(const float* x, size_t n) {
    if (n < 2) return 0.0f;

    std::size_t i = 0;
    float sum = 0.0f;
    while (i < n) {
        svbool_t pg = svwhilelt_b32((uint64_t)i, (uint64_t)n);
        svfloat32_t vx = svld1(pg, &x[i]);
        sum += svaddv_f32(pg, vx);
        i += svcntw();
    }
    const float mean = n ? sum / (float)n : 0.0f;

    i = 0;
    float ss = 0.0f;
    svfloat32_t vmean = svdup_f32(mean);
    while (i < n) {
        svbool_t pg = svwhilelt_b32((uint64_t)i, (uint64_t)n);
        svfloat32_t v  = svld1(pg, &x[i]);
        svfloat32_t d  = svsub_f32_x(pg, v, vmean);
        svfloat32_t sq = svmul_f32_x(pg, d, d);
        ss += svaddv_f32(pg, sq);
        i += svcntw();
    }
    return sqrtf(ss / (float)n);
}

