#include <arm_sve.h>
#include <cstddef>

void mscd_empty(const int32_t *v, const uint8_t *m, int n, int32_t th,
                int64_t *so, int32_t *co) {

  if (n <= 0 || !v || !m) {
    *so = 0;
    *co = 0;
    return;
  }

  int64_t sum = 0LL;
  int32_t cnt = 0;

  std::size_t i = 0ULL;

  while (i < n) {

    const svbool_t pg = svwhilelt_b32((uint64_t)i, (uint64_t)n);

    const int nl = svcntp_b32(pg, pg);

    const svuint32_t idx = svindex_u32((uint32_t)i, 1U);

    const svbool_t pe =
        svcmpeq_n_u32(pg, svand_u32_z(pg, idx, svdup_n_u32(1u)), 0u);

    const svint32_t x = svld1_s32(pg, &(v[i]));

    const svbool_t po =
        svcmpne_n_s32(pg, svand_s32_z(pg, x, svdup_n_s32(1)), 0);

    const svbool_t gt = svcmpgt_s32(pg, x, svdup_n_s32(th));

    const svuint32_t mv = svld1ub_u32(pg, &(m[i]));

    const svbool_t pm = svcmpne_n_u32(pg, mv, 0u);

    const svbool_t sel =
        svand_b_z(pg, svand_b_z(pg, pe, pm), svand_b_z(pg, po, gt));

    const int nsel = svcntp_b32(pg, sel);

    const svint32_t xs = svsel_s32(sel, x, svdup_n_s32(0));

    const svint64_t lo64 = svunpklo_s64(xs);
    const svint64_t hi64 = svunpkhi_s64(xs);
    const int64_t part = svaddv_s64(svptrue_b64(), lo64) +
                         svaddv_s64(svptrue_b64(), hi64);

    sum += part;

    cnt += nsel;

    i += svcntw();
  }

  *so = sum;
  *co = cnt;
}

