#include <cstddef>
#include <arm_sve.h>
void simd_sub_f64_sve(const double *a, const double *b, double *r,
                             std::size_t n) {
  std::size_t i = 0;
  for (; i < n; i += svcntd()) {
    svbool_t pg = svwhilelt_b64(i, n);
    svfloat64_t va = svld1(pg, &a[i]);
    svfloat64_t vb = svld1(pg, &b[i]);
    svfloat64_t vr = svsub_f64_m(pg, va, vb);
    svst1(pg, &r[i], vr);
  }
}

