/*
The inputs to this function are:
- `src`: a pointer to an array of 32-bit unsigned integers (input elements).
- `dst`: a pointer to an array of 8-bit unsigned integers where the results are written (output elements).
- `n`: the number of elements to process.

The function processes each of the first `n` elements sequentially:
for (i = 0; i < n; i++) {
    read the 32-bit value `v` from src[i];
    if (v is greater than 255) set `v` to 255;
    write the lower 8 bits of `v` into dst[i].
}
If the source value is within the range 0..255, it is copied directly; otherwise, it is saturated to 255.

Preconditions:
- The pointers `src` and `dst` must be valid and non‑null.
- The arrays pointed to by `src` and `dst` must each have at least `n` elements of accessible memory.
- The function does not return a value (void).
The requirement is to implement the function with SVE (Arm C Language Extensions (ACLE) for the Arm Scalable Vector Extension (SVE)) intrinsics for parallelism.
*/
void saturate_narrow_u32_to_u8_sizet(const uint32_t *src, uint8_t *dst, size_t n) {
}

#include <arm_sve.h>
#include <stdint.h>
#include <stddef.h>
#include <limits.h>

void saturate_narrow_u32_to_u8_sizet(const uint32_t *src, uint8_t *dst, size_t n) {
    size_t i = 0;
    const size_t vl = svcntw();
    while (i < n) {
        svbool_t pg = svwhilelt_b32((uint64_t)i, (uint64_t)n);
        svuint32_t v = svld1_u32(pg, src + i);
        v = svmin_u32_x(pg, v, svdup_u32((uint32_t)UINT8_MAX));
        svst1b_u32(pg, dst + i, v);
        i += vl;
    }
}

