double check_convergence(double **pwm1, double **pwm2, int pwmLen)
{
    if (!pwmLen)
        return 0;

    const std::size_t nRows = (std::size_t)pwmLen;
    const std::size_t nCols = 4;

    double dif = 0;


    for (std::size_t iRow = 0; iRow < nRows; ++iRow)
    {
        const double *pRowPwm1 = pwm1[iRow];
        const double *pRowPwm2 = pwm2[iRow];

        std::size_t iCol = 0;
        while (iCol < nCols)
        {
            svbool_t pgCol = svwhilelt_b64((uint64_t)iCol, (uint64_t)nCols);

            svfloat64_t vPwm1 = svld1_f64(pgCol, &pRowPwm1[iCol]);
            svfloat64_t vPwm2 = svld1_f64(pgCol, &pRowPwm2[iCol]);

            svfloat64_t vDiff = svabd_f64_x(svptrue_b64(), vPwm1, vPwm2);

            svfloat64_t vMax = svdup_n_f64(dif);
            svbool_t    pLarger = svcmpgt_f64(pgCol, vDiff, vMax);

            svfloat64_t vNewMax = svsel_f64(pLarger, vDiff, vMax);
            float64_t   fOverallMax = svmaxv_f64(svptrue_b64(), vNewMax);

            if (fOverallMax > dif)
                dif = fOverallMax;

            iCol += svcntd();
        }
    }

    return dif;
}

