void cosine_distance_f32_sve(const float *input1, const float *input2,
                             uint64_t size, float *output) {
  uint64_t i = 0;
  svfloat32_t dot_prod_vec = svdup_f32(0.0f);
  svbool_t pg;
  svfloat32_t mag_sq_vec_1 = svdup_f32(0.0f);
  svfloat32_t mag_sq_vec_2 = svdup_f32(0.0f);

  int chunks = size / svcntw();
  for (int j = 0; j < chunks; i += svcntw(), j++) {
    pg = svwhilelt_b32(i, size);
    svfloat32_t vec1 = svld1(pg, input1 + i);
    svfloat32_t vec2 = svld1(pg, input2 + i);
    dot_prod_vec = svmla_f32_x(pg, dot_prod_vec, vec1, vec2);
    mag_sq_vec_1 = svmla_f32_x(pg, mag_sq_vec_1, vec1, vec1);
    mag_sq_vec_2 = svmla_f32_x(pg, mag_sq_vec_2, vec2, vec2);
  }

  float magnitudeSq1 = svaddv_f32(svptrue_b32(), mag_sq_vec_1);
  float magnitudeSq2 = svaddv_f32(svptrue_b32(), mag_sq_vec_2);
  float dotProduct = svaddv_f32(svptrue_b32(), dot_prod_vec);


  for (; i < size; ++i) {
    float val1 = input1[i];
    float val2 = input2[i];
    dotProduct += val1 * val2;
    magnitudeSq1 += val1 * val1;
    magnitudeSq2 += val2 * val2;
