int mmb_bt_f(const int32_t *v, const uint8_t *m, int n, int32_t thr,
             int32_t *best_o) {
  int32_t best = INT32_MAX;

  if (n <= 0 || !v || !m || !best_o)
    return 0;

  std::size_t i = 0;
  while (i < n) {
    svbool_t pg = svwhilelt_b32((uint64_t)i, (uint64_t)n);

    svuint32_t mv = svld1ub_u32(svptrue_b32(), &(m[(std::size_t)(i)]));

    svbool_t pm = svcmpne_n_u32(pg, mv, 0u);

    svint32_t vv = svld1_s32(pg, &(v[(std::size_t)(i)]));

    svbool_t pt = svcmpge_n_s32(pg, vv, thr);

    svbool_t sel = svand_b_z(pg, pm, pt);

    int32_t part = svminv_s32(sel, vv);

    if (part < best) {
