int lstr(const char *const *a, int n) {
  if (!a || n <= 0)
    return -1;

  int best_len = -1;
  int best_idx = -1;

  for (int i = 0; i < n; ++i) {
    const char *s = a[i];
    int len = 0;

    if (s) {
      std::size_t offset = 0;
      for (;;) {
        svsetffr();
        svuint8_t bytes = svldff1_u8(svptrue_b8(), (const uint8_t *)(s + offset));
        svbool_t valid = svrdffr();
        svbool_t zero = svcmpeq_n_u8(valid, bytes, 0);

        if (svptest_any(svptrue_b8(), zero)) {
          svbool_t before_zero = svbrkb_b_z(svptrue_b8(), zero);
          len = (int)(offset + svcntp_b8(svptrue_b8(), before_zero));
          break;
        }

        uint64_t advanced = svcntp_b8(svptrue_b8(), valid);
        offset += advanced ? advanced : 1;
      }
    }

    if (len > best_len) {
      best_len = len;
      best_idx = i;
    }
  }

  return best_idx;
}

