            svfloat64_t data_imag = svld1_gather_index(pg, a + 1, gat_ind);

            gat_ind = svadd_m(cmp, gat_ind, 2);
            gat_ind = svadd_m(svnot_z(pg, cmp), gat_ind, lda_vec);

            svst2(pg, b, svcreate2(data_vec_real, data_imag));

