    size_t j = 0;
    const size_t vl = svcntw();
    while (j < (size_t)num_output_bytes) {
        svbool_t pg = svwhilelt_b32((uint64_t)j, (uint64_t)num_output_bytes);
        svuint32_t lane_idx = svindex_u32((uint32_t)j, 1);

        svuint32_t base_byte_off = svmul_n_u32_x(pg, lane_idx, 8u);

        svint32_t lo_bound = svdup_s32(0);
        svint32_t hi_bound = svdup_s32(3);
        svint32_t mask2 = svdup_s32(0x03);
        svint32_t packed = svdup_s32(0);

        svuint32_t off_0 = svadd_n_u32_x(pg, base_byte_off, 0u);
        svint32_t v_0 = svld1sh_gather_u32offset_s32(pg, src, off_0);
        v_0 = svmax_s32_x(pg, v_0, lo_bound);
        v_0 = svmin_s32_x(pg, v_0, hi_bound);
        v_0 = svand_s32_x(pg, v_0, mask2);
        packed = svorr_s32_x(pg, packed, v_0);

        svuint32_t off_1 = svadd_n_u32_x(pg, base_byte_off, 2u);
        svint32_t v_1 = svld1sh_gather_u32offset_s32(pg, src, off_1);
        v_1 = svmax_s32_x(pg, v_1, lo_bound);
        v_1 = svmin_s32_x(pg, v_1, hi_bound);
        v_1 = svand_s32_x(pg, v_1, mask2);
        packed = svorr_s32_x(pg, packed, svlsl_n_s32_x(pg, v_1, 2));

        svuint32_t off_2 = svadd_n_u32_x(pg, base_byte_off, 4u);
        svint32_t v_2 = svld1sh_gather_u32offset_s32(pg, src, off_2);
        v_2 = svmax_s32_x(pg, v_2, lo_bound);
        v_2 = svmin_s32_x(pg, v_2, hi_bound);
        v_2 = svand_s32_x(pg, v_2, mask2);
        packed = svorr_s32_x(pg, packed, svlsl_n_s32_x(pg, v_2, 4));

        svuint32_t off_3 = svadd_n_u32_x(pg, base_byte_off, 6u);
        svint32_t v_3 = svld1sh_gather_u32offset_s32(pg, src, off_3);
