float dot_product(int num_elems)
{
    const float initial_val = 2.0f;
    std::size_t n = num_elems;

    if(n == 0)
        return 0.0f;

    float a[n];
    float b[n];


    float a_val = initial_val;
    std::size_t i = 0;
    while(i < n)
    {
        a[i] = a_val;
        ++i;
        ++a_val;
    }


    std::size_t j = 0;
    while(j < n)
    {
        b[j] = initial_val;
        ++j;
    }


    std::size_t k = 0;
    float acc = 0.0f;

    while(k < n)
    {
        svbool_t pg = svwhilelt_b32((uint64_t)(k), (uint64_t)(n));
        svfloat32_t va = svld1_f32(pg, &a[k]);
        svfloat32_t vb = svld1_f32(pg, &b[k]);

        svfloat32_t prod = svmul_f32_x(pg, va, vb);
        acc += svaddv_f32(svptrue_b32(), prod);

        k += svcntw();
    }

    return acc;
}

