void requantize_u8_to_u8(const uint8_t *src, float in_scale, int32_t in_zp, float out_scale, int32_t out_zp, uint8_t *dst, int n) {
    if (n <= 0) return;
    size_t i = 0;
    const size_t vl = svcntw();
    float scale_ratio = in_scale / out_scale;
    svfloat32_t ratio_v = svdup_n_f32(scale_ratio);
    svfloat32_t out_zp_v = svdup_n_f32((float)out_zp);
    svint32_t in_zp_v = svdup_s32(in_zp);
    svint32_t lo = svdup_s32(0);
    svint32_t hi = svdup_s32(255);
    while (i < (size_t)n) {
        svbool_t pg = svwhilelt_b32((uint64_t)i, (uint64_t)n);
        svuint32_t u32 = svld1ub_u32(pg, src + i);
        svint32_t s32 = svreinterpret_s32_u32(u32);
        s32 = svsub_s32_x(pg, s32, in_zp_v);
        svfloat32_t f = svcvt_f32_s32_x(pg, s32);
        svfloat32_t scaled = svmla_f32_x(pg, out_zp_v, f, ratio_v);
        svfloat32_t rounded = svrintn_f32_x(pg, scaled);
        svint32_t out32 = svcvt_s32_f32_x(pg, rounded);
