float mirror_pair_dot_product(const float *a, int n) {
    if (n <= 0) return 0.0f;
    int vl = (int)svcntw();
    int i = 0;
    svbool_t pg_all = svptrue_b32();
    svfloat32_t acc = svdup_n_f32(0.0f);
    while (i + vl <= n) {
        svfloat32_t fwd = svld1_f32(pg_all, a + i);
        svfloat32_t rev_raw = svld1_f32(pg_all, a + (n - i - vl));
        svfloat32_t rev = svrev_f32(rev_raw);
        acc = svmla_f32_x(pg_all, acc, fwd, rev);
        i += vl;
    }
    float total = svaddv_f32(pg_all, acc);
    for (; i < n; ++i) {
        total += a[i] * a[n - 1 - i];
    }
    return total;
}

