#include <cstdint>

void p5o_f32_to_f16_clamp_store_04(const float *src, __fp16 *dst, size_t n, float scale, float lo, float hi) {
  const size_t vl = svcntw();
  const svfloat32_t vscale = svdup_n_f32(scale);
  const svfloat32_t vlo = svdup_n_f32(lo);
  const svfloat32_t vhi = svdup_n_f32(hi);

  for (size_t i = 0; i < n; i += vl) {
    const size_t chunk = (n - i < vl) ? (n - i) : vl;
    svbool_t pg32 =
        svwhilelt_b32(static_cast<uint64_t>(i), static_cast<uint64_t>(n));
    svfloat32_t value = svld1(pg32, src + i);
    value = svmul_f32_x(pg32, value, vscale);
    value = svmax_f32_x(pg32, value, vlo);
    value = svmin_f32_x(pg32, value, vhi);
    svfloat16_t narrowed = svcvt_f16_f32_x(pg32, value);
    narrowed = svuzp1_f16(narrowed, narrowed);
    svbool_t pg16 =
        svwhilelt_b16(static_cast<uint64_t>(0), static_cast<uint64_t>(chunk));
    svst1(pg16, dst + i, narrowed);
  }
}

