void p5o_prefix_min_i32_04(const int32_t *src, int32_t *dst, size_t n) {
    size_t vl = svcntw();
    svbool_t all = svptrue_b32();
    svint32_t id = svdup_n_s32(INT_MAX);
    int32_t c = INT_MAX;
    size_t i = 0;
    while (i < n) {
        svbool_t pg = svwhilelt_b32((uint64_t)i, (uint64_t)n);
