void p6pv6_i16_row_scatter_abs_02(const int16_t *src, int16_t *dst, size_t rows, size_t cols, size_t block, int16_t param) {
    (void)param;
    if (block == 0) return;
    const uint32_t stride = (uint32_t)cols;
    for (size_t bc = 0; bc < cols; bc += block) {
        size_t cend = bc + block < cols ? bc + block : cols;
        for (size_t c = bc; c < cend; ++c) {
